mapper.select:
SELECT

FROM comments c
JOIN users u ON u.id = c.user_id
WHERE c.review_id = #{reviewId}
ORDER BY c.created_at ASC, c.id ASC
LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*)
FROM comments
WHERE review_id = #{reviewId}

mapper.update:
UPDATE comments
SET content = #{content}
WHERE id = #{id}
  AND user_id = #{userId}

mapper.delete:
DELETE FROM comments
WHERE id = #{commentId}
  AND user_id = #{userId}
